#include "luca/config.h"
#include "luca/irc.h"
#include "luca/lua_runtime.h"
#include "luca/transport.h"
#include "luca/sasl.h"
#include "luca/pbmp.h"
#include "luca/botai.h"
#include <pthread.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
struct conn{struct luca_transport*t;};struct pbctx{const char*path;struct luca_pbmp_state*s;};
static int sendline(void*o,const char*s){struct conn*c=o;return luca_transport_write(c->t,s,strlen(s))||luca_transport_write(c->t,"\r\n",2)?-1:0;}static void*pbthread(void*v){struct pbctx*c=v;luca_pbmp_serve(c->path,c->s);return NULL;}
int main(int argc,char**argv){struct luca_config cfg;if(argc!=2||luca_config_load(argv[1],&cfg)){fprintf(stderr,"usage: luca <config>\n");return 2;}struct luca_botai ai;int ai_enabled=0;if(cfg.botai_url[0]){if(!luca_botai_init(&ai,cfg.botai_url,cfg.botai_expert,(long)cfg.botai_timeout_seconds*1000L)&&!luca_botai_compatible(&ai)){ai_enabled=1;fprintf(stderr,"BotAI integration enabled\n");}else fprintf(stderr,"BotAI unavailable/incompatible; continuing without AI\n");}struct luca_command_queue commands;if(luca_command_queue_init(&commands)){fprintf(stderr,"command queue unavailable\n");return 1;}struct luca_log log;if(luca_log_init(&log)){fprintf(stderr,"log buffer unavailable\n");return 1;}struct luca_channel_registry channels;if(luca_channel_registry_init(&channels,cfg.channel)){fprintf(stderr,"channel registry unavailable\n");return 1;}struct luca_pbmp_state ps={cfg.nick,cfg.server,cfg.channel,0,0,&commands,cfg.script,0,0,0,0,0,&log,cfg.port,cfg.user,cfg.realname,cfg.script,cfg.tls,cfg.sasl,cfg.reconnect_seconds,&channels};struct pbctx pc={cfg.pbmp_socket,&ps};pthread_t pt;if(pthread_create(&pt,NULL,pbthread,&pc)==0)pthread_detach(pt);else fprintf(stderr,"PBMP socket unavailable\n");for(;;){struct conn c={luca_transport_connect(cfg.server,cfg.port,cfg.tls)};if(!c.t){atomic_store(&ps.connected,0);atomic_store(&ps.channel_state,0);sleep(cfg.reconnect_seconds);continue;}atomic_store(&ps.connected,1);atomic_store(&ps.session_started,(long)time(NULL));luca_log_add(&log,"info","IRC session connected");char b[1024];sendline(&c,"CAP LS 302");snprintf(b,sizeof b,"NICK %s",cfg.nick);sendline(&c,b);snprintf(b,sizeof b,"USER %s 0 * :%s",cfg.user,cfg.realname);sendline(&c,b);struct luca_lua*r=luca_lua_open(cfg.script,sendline,&c);atomic_store(&ps.module_active,r?1:0);int cap_done=0,joined=0;while(luca_transport_readline(c.t,b,sizeof b)>0){atomic_fetch_add(&ps.rx_lines,1);struct luca_command queued;while(!luca_command_dequeue(&commands,&queued)){if(queued.type==LUCA_COMMAND_IRC)sendline(&c,queued.line);else if(queued.type==LUCA_COMMAND_MODULE_RELOAD){struct luca_lua*next=luca_lua_open(cfg.script,sendline,&c);if(next){struct luca_lua*old=r;r=next;atomic_store(&ps.module_active,1);luca_lua_close(old);luca_log_add(&log,"info","Lua module reloaded");}else{atomic_store(&ps.module_active,r?1:0);fprintf(stderr,"Lua reload rejected; previous runtime remains active\\n");luca_log_add(&log,"warn","Lua reload rejected; previous runtime remains active");}}}struct luca_irc_message m;if(luca_irc_parse(b,&m))continue;if(!strcmp(m.command,"PING")&&m.nparams){char out[600];snprintf(out,sizeof out,"PONG :%s",m.params[0]);sendline(&c,out);}if(!strcmp(m.command,"CAP")&&m.nparams>=3&&!strcmp(m.params[1],"LS")){if(cfg.sasl&&strstr(m.params[m.nparams-1],"sasl"))sendline(&c,"CAP REQ :sasl");else{sendline(&c,"CAP END");cap_done=1;}}else if(!strcmp(m.command,"CAP")&&m.nparams>=3&&!strcmp(m.params[1],"ACK")&&strstr(m.params[m.nparams-1],"sasl")){sendline(&c,"AUTHENTICATE PLAIN");}else if(!strcmp(m.command,"AUTHENTICATE")&&m.nparams&&cfg.sasl){char enc[768],out[800];if(!luca_sasl_plain(cfg.sasl_user,cfg.sasl_password,enc,sizeof enc)){snprintf(out,sizeof out,"AUTHENTICATE %s",enc);sendline(&c,out);}}else if(!strcmp(m.command,"903")){sendline(&c,"CAP END");cap_done=1;}else if(!strcmp(m.command,"904")||!strcmp(m.command,"905")||!strcmp(m.command,"906")||!strcmp(m.command,"907")){fprintf(stderr,"SASL authentication failed\n");break;}if(cap_done&&!joined&&(!strcmp(m.command,"001")||!strcmp(m.command,"903"))){pthread_mutex_lock(&channels.mu);for(unsigned ci=0;ci<channels.count;ci++)if(channels.items[ci].wanted){snprintf(b,sizeof b,"JOIN %s",channels.items[ci].name);sendline(&c,b);}pthread_mutex_unlock(&channels.mu);atomic_store(&ps.channel_state,1);joined=1;}if(!strcmp(m.command,"JOIN")&&m.nparams&&luca_irc_prefix_is_nick(m.prefix,cfg.nick)){luca_channel_registry_observe(&channels,m.params[0],1);if(!luca_irc_casecmp(m.params[0],cfg.channel))atomic_store(&ps.channel_state,2);}else if(!strcmp(m.command,"PART")&&m.nparams&&luca_irc_prefix_is_nick(m.prefix,cfg.nick)){luca_channel_registry_observe(&channels,m.params[0],0);if(!luca_irc_casecmp(m.params[0],cfg.channel))atomic_store(&ps.channel_state,1);}else if(!strcmp(m.command,"KICK")&&m.nparams>=2&&luca_irc_casecmp(m.params[1],cfg.nick)==0){luca_channel_registry_observe(&channels,m.params[0],0);if(!luca_irc_casecmp(m.params[0],cfg.channel))atomic_store(&ps.channel_state,1);}if(ai_enabled&&!strcmp(m.command,"PRIVMSG")&&m.nparams>=2){const char*text=m.params[m.nparams-1];if(!strncmp(text,"!ai ",4)&&text[4]){char reply[1024],nick[128]={0},out[1400];const char*bang=strchr(m.prefix,'!');size_t nn=bang?(size_t)(bang-m.prefix):strlen(m.prefix);if(nn>=sizeof nick)nn=sizeof nick-1;memcpy(nick,m.prefix,nn);const char*target=(m.params[0][0]=='#'||m.params[0][0]=='&')?m.params[0]:nick;if(!luca_botai_chat(&ai,text+4,reply,sizeof reply)){snprintf(out,sizeof out,"PRIVMSG %s :%s",target,reply);sendline(&c,out);}else{snprintf(out,sizeof out,"NOTICE %s :BotAI is temporarily unavailable",nick);sendline(&c,out);}continue;}}luca_lua_event(r,&m);}atomic_store(&ps.connected,0);atomic_store(&ps.channel_state,0);atomic_store(&ps.module_active,0);pthread_mutex_lock(&channels.mu);for(unsigned ci=0;ci<channels.count;ci++){channels.items[ci].joined=0;channels.items[ci].parting=0;}pthread_mutex_unlock(&channels.mu);luca_log_add(&log,"warn","IRC session disconnected");luca_lua_close(r);luca_transport_close(c.t);atomic_fetch_add(&ps.reconnects,1);sleep(cfg.reconnect_seconds);}}
